INSERT INTO `produtos` (`id`, `codigo`, `codigo_cq`, `nome`, `descricao`, `anotacoes`, `local_uso`, `ativo`, `created_at`, `updated_at`, `preco`, `categoria`, `preco_custo`, `estoque_minimo`, `unidade`, `tiny_id`, `modo_uso`, `tiny_sync_at`) VALUES (36, 'AQUELANE-8-G30', NULL, 'Loção Clareadora Aquelane 8', 'Hidroquisan 8,0%\\nNeodeline 6,0%\\nVitessence 6,0%\\nMelavan qs\\nB. Aquelane qsp 30g', 'Aplique de manhã, antes do creme do dia, em toda a face ou como orientado. Se indicado, use no dorso das mãos e nos antebraços.', 'face', 1, '2026-01-11 09:46:41', '2026-01-18 09:50:26', 118.83, 'Cremes', 100, 10, 'UN', 123, 'Aplique de manhã, antes do creme do dia, em toda a face ou como orientado. Se indicado, use no dorso das mãos e nos antebraços.', NULL);
INSERT INTO `produtos` (`id`, `codigo`, `codigo_cq`, `nome`, `descricao`, `anotacoes`, `local_uso`, `ativo`, `created_at`, `updated_at`, `preco`, `categoria`, `preco_custo`, `estoque_minimo`, `unidade`, `tiny_id`, `modo_uso`, `tiny_sync_at`) VALUES (37, 'MAOS-NOITE-R0,035H12-DYN3', NULL, 'Creme Mãos Noite Rejuvenescedor', 'Tretinoína 0,035%\\nHidroquisan 12%\\nVitessence 6,0%\\nNeolipossome VC qs\\nB. Hydraction Suisse 30,0%\\nB. Neodeline Nutrissome qsp 30g', 'Uso: aplicar fina camada a noite nas mãos e antebraços. Inicie alternando as noites conforme orientação. Se ocorrer vermelhidão, interrompa o uso e contate-nos.', 'maos', 1, '2026-01-11 09:46:41', '2026-01-11 11:24:22', 96.62, NULL, NULL, NULL, 'UN', NULL, NULL, NULL);
