INSERT INTO `produtos` (`id`, `codigo`, `codigo_cq`, `nome`, `descricao`, `anotacoes`, `local_uso`, `ativo`, `created_at`, `updated_at`, `preco`, `categoria`, `preco_custo`, `estoque_minimo`, `unidade`, `tiny_id`, `modo_uso`, `tiny_sync_at`) VALUES (39, 'CORPO-CREME', NULL, 'Creme do Corpo Hydraessential', 'Nutradvance 6,0%\\nHydraessential qsp 200g', 'Aplique em todo o corpo após o banho. Se necessário, aplicar mais vezes ao dia. Uso ininterrupto para ação anti-flacidez, anti-estrias, anti-idade e nutrição profunda.', 'corpo', 1, '2026-01-11 09:46:41', '2026-01-11 11:24:22', 65.54, NULL, NULL, NULL, 'UN', NULL, NULL, NULL);
INSERT INTO `produtos` (`id`, `codigo`, `codigo_cq`, `nome`, `descricao`, `anotacoes`, `local_uso`, `ativo`, `created_at`, `updated_at`, `preco`, `categoria`, `preco_custo`, `estoque_minimo`, `unidade`, `tiny_id`, `modo_uso`, `tiny_sync_at`) VALUES (40, 'CAPILVELT', NULL, 'Loção Capilar Capilvelt', 'Minoxidil 5%\\nD-pantenol 1%\\nVitessence qs\\nCapilvelt Pro FC 5%\\nCapilvelt Acqua 15%\\nÁgua purificada 10%\\nSérum Capilar pH 4,5 qsp 100mL', 'Modo de uso: Aplicar 6 puffs no couro cabeludo (seco ou quase seco) 1 ou 2 vezes ao dia, massageando suavemente para espalhar o produto na pele do couro cabeludo. Evitar lavar os cabelos por 6 horas após a aplicação. O uso de secador, géis ou cremes capilares não interfere no efeito. Seu uso é diário e contínuo, para não perder os resultados que se iniciam dentro de 3 a 4 meses.', 'cabelo', 1, '2026-01-11 09:46:41', '2026-01-11 11:24:22', 133.18, NULL, NULL, NULL, 'UN', NULL, NULL, NULL);
